# %%
# Syntax reference: kaggle_benchmarks_reference.md
import os
import glob
import json
import time
import zlib
import base64
from concurrent.futures import ThreadPoolExecutor, as_completed
from dotenv import load_dotenv
load_dotenv()
import kaggle_benchmarks as kbench

# Embedded compressed datasets (fallback if Kaggle dataset not mounted)
SEEN_DATA_B64 = ""
UNSEEN_DATA_B64 = ""

def load_jsonl_samples(filename, b64_fallback):
    search_dirs = [
        "/kaggle/input",
        "data/custom_vi",
        "."
    ]
    for sdir in search_dirs:
        if os.path.exists(sdir):
            matches = glob.glob(f"{sdir}/**/{filename}", recursive=True)
            if matches:
                with open(matches[0], "r", encoding="utf-8") as f:
                    return [json.loads(line) for line in f if line.strip()]
    
    raw_bytes = zlib.decompress(base64.b64decode(b64_fallback))
    lines = raw_bytes.decode("utf-8").splitlines()
    return [json.loads(line) for line in lines if line.strip()]

def match_call(c1, c2):
    if c1.get("name") != c2.get("name"):
        return False
    a1 = c1.get("arguments", {})
    a2 = c2.get("arguments", {})
    if set(a1.keys()) != set(a2.keys()):
        return False
    for k, v1 in a1.items():
        v2 = a2[k]
        if isinstance(v1, (int, float)) and isinstance(v2, (int, float)):
            if abs(v1 - v2) > 1e-4:
                return False
        elif str(v1).strip().lower() != str(v2).strip().lower():
            return False
    return True

def is_exact_match(pred_calls, gold_calls):
    if len(pred_calls) != len(gold_calls):
        return False
    matched = [False] * len(gold_calls)
    for p in pred_calls:
        found = False
        for i, g in enumerate(gold_calls):
            if not matched[i] and match_call(p, g):
                matched[i] = True
                found = True
                break
        if not found:
            return False
    return all(matched)

def evaluate_single_sample(llm, item):
    t0 = time.time()
    extra_kwargs = {}
    if "gpt" in str(llm.model).lower() or "luna" in str(llm.model).lower():
        extra_kwargs["reasoning_effort"] = "none"

    openai_tools = [
        {
            "type": "function",
            "function": {
                "name": t["name"],
                "description": t.get("description", ""),
                "parameters": t.get("parameters", {"type": "object", "properties": {}}),
            }
        }
        for t in item.get("tools", [])
    ]

    gold_calls = item.get("function_calls", [])
    is_positive = len(gold_calls) > 0
    has_syntax_error = False

    try:
        resp = llm.client.chat.completions.create(
            model=llm.model,
            messages=[
                {
                    "role": "system",
                    "content": "Bạn là trợ lý AI hữu ích. Nếu người dùng yêu cầu hành động cần công cụ, hãy gọi đúng các hàm và truyền tham số chính xác. Nếu yêu cầu không liên quan đến công cụ nào được cung cấp, TUYỆT ĐỐI KHÔNG gọi công cụ nào."
                },
                {"role": "user", "content": item["query"]}
            ],
            tools=openai_tools,
            tool_choice="auto",
            **extra_kwargs
        )
        elapsed_ms = (time.time() - t0) * 1000

        pred_calls = []
        for tc in (resp.choices[0].message.tool_calls or []):
            fn_name = tc.function.name
            try:
                raw_args = tc.function.arguments
                if isinstance(raw_args, dict):
                    fn_args = raw_args
                elif isinstance(raw_args, str) and raw_args.strip():
                    fn_args = json.loads(raw_args)
                else:
                    fn_args = {}
            except Exception:
                has_syntax_error = True
                fn_args = {}
            pred_calls.append({"name": fn_name, "arguments": fn_args})

        gold_tool_names = sorted([c["name"] for c in gold_calls])
        pred_tool_names = sorted([c["name"] for c in pred_calls])

        if is_positive:
            tool_correct = (gold_tool_names == pred_tool_names)
            neg_correct = None
            exact_match = is_exact_match(pred_calls, gold_calls) and not has_syntax_error
        else:
            # Negative (Non-FC): Correct if NO tool was called
            tool_correct = None
            neg_correct = (len(pred_calls) == 0 and not has_syntax_error)
            exact_match = neg_correct

        return {
            "id": item["id"],
            "is_positive": is_positive,
            "tool_correct": tool_correct,
            "neg_correct": neg_correct,
            "exact_match": exact_match,
            "syntax_error": has_syntax_error,
            "gold_tools": gold_tool_names,
            "pred_tools": pred_tool_names,
            "latency_ms": round(elapsed_ms, 1),
            "error": None
        }
    except Exception as e:
        elapsed_ms = (time.time() - t0) * 1000
        return {
            "id": item["id"],
            "is_positive": is_positive,
            "tool_correct": False if is_positive else None,
            "neg_correct": False if not is_positive else None,
            "exact_match": False,
            "syntax_error": True,
            "gold_tools": [c["name"] for c in gold_calls],
            "pred_tools": [],
            "latency_ms": round(elapsed_ms, 1),
            "error": str(e)
        }

def compute_split_metrics(results, split_name):
    total = len(results)
    pos_results = [r for r in results if r["is_positive"]]
    neg_results = [r for r in results if not r["is_positive"]]

    pos_total = len(pos_results)
    neg_total = len(neg_results)

    tool_correct = sum(1 for r in pos_results if r["tool_correct"])
    neg_correct = sum(1 for r in neg_results if r["neg_correct"])
    exact_match = sum(1 for r in results if r["exact_match"])
    syntax_errors = sum(1 for r in results if r["syntax_error"])
    latencies = [r["latency_ms"] for r in results if r["latency_ms"] > 0]

    tool_acc = round(tool_correct / pos_total * 100, 2) if pos_total else 0.0
    non_fc_rec = round(neg_correct / neg_total * 100, 2) if neg_total else 0.0
    em_arga = round(exact_match / total * 100, 2) if total else 0.0
    syntax_err = round(syntax_errors / total * 100, 2) if total else 0.0
    avg_lat = round(sum(latencies) / len(latencies), 1) if latencies else 0.0

    return {
        f"{split_name}_total": total,
        f"{split_name}_pos_total": pos_total,
        f"{split_name}_neg_total": neg_total,
        f"{split_name}_tool_acc_pct": tool_acc,
        f"{split_name}_arga_em_pct": em_arga,
        f"{split_name}_non_fc_rec_pct": non_fc_rec,
        f"{split_name}_syntax_err_pct": syntax_err,
        f"{split_name}_avg_latency_ms": avg_lat
    }

# %%
@kbench.task(name="tool-calling-vi-full", description="Full benchmark on 1,600 CustomTools-VI samples matching Table 2 paper metrics")
def tool_calling_vi_full(llm) -> dict:
    seen_samples = load_jsonl_samples("test_seen.jsonl", SEEN_DATA_B64)
    unseen_samples = load_jsonl_samples("test_unseen.jsonl", UNSEEN_DATA_B64)

    # Push guard: Kaggle auto-runs default model (3.7) upon push.
    # Keep push verification fast and cheap (6 samples: 4 pos + 2 neg).
    is_push_verification = "3.7" in str(llm.model)
    if is_push_verification:
        seen_samples = seen_samples[:3]
        unseen_samples = unseen_samples[:3]

    def run_eval_batch(samples):
        results = []
        with ThreadPoolExecutor(max_workers=8) as executor:
            future_to_item = {executor.submit(evaluate_single_sample, llm, item): item for item in samples}
            for future in as_completed(future_to_item):
                results.append(future.result())
        return results

    seen_results = run_eval_batch(seen_samples)
    unseen_results = run_eval_batch(unseen_samples)

    seen_metrics = compute_split_metrics(seen_results, "seen")
    unseen_metrics = compute_split_metrics(unseen_results, "unseen")
    all_metrics = compute_split_metrics(seen_results + unseen_results, "overall")

    print(f"\n=======================================================")
    print(f"📊 KẾT QUẢ BENCHMARK CHO: {llm.model}")
    print(f"=======================================================")
    print(f"🔹 [SEEN   (800 mẫu)] Tool Acc: {seen_metrics['seen_tool_acc_pct']}% | ArgA/EM: {seen_metrics['seen_arga_em_pct']}% | Non-FC Rec: {seen_metrics['seen_non_fc_rec_pct']}% | Lỗi cú pháp: {seen_metrics['seen_syntax_err_pct']}% | Trễ: {seen_metrics['seen_avg_latency_ms']} ms")
    print(f"🔹 [UNSEEN (800 mẫu)] Tool Acc: {unseen_metrics['unseen_tool_acc_pct']}% | ArgA/EM: {unseen_metrics['unseen_arga_em_pct']}% | Non-FC Rec: {unseen_metrics['unseen_non_fc_rec_pct']}% | Lỗi cú pháp: {unseen_metrics['unseen_syntax_err_pct']}% | Trễ: {unseen_metrics['unseen_avg_latency_ms']} ms")
    print(f"🔹 [OVERALL (1.6k )] Tool Acc: {all_metrics['overall_tool_acc_pct']}% | ArgA/EM: {all_metrics['overall_arga_em_pct']}% | Non-FC Rec: {all_metrics['overall_non_fc_rec_pct']}% | Trễ: {all_metrics['overall_avg_latency_ms']} ms")
    print(f"=======================================================\n")

    kbench.assertions.assert_true(
        all_metrics["overall_arga_em_pct"] >= 0.0,
        expectation=f"Overall ArgA/EM should be >= 0%, got {all_metrics['overall_arga_em_pct']}%"
    )

    output = {
        "model": llm.model,
        "total_samples": len(seen_results) + len(unseen_results),
        # Table 2 Columns for Paper
        "seen_tool_acc_pct": seen_metrics["seen_tool_acc_pct"],
        "seen_arga_em_pct": seen_metrics["seen_arga_em_pct"],
        "seen_non_fc_rec_pct": seen_metrics["seen_non_fc_rec_pct"],
        "seen_syntax_err_pct": seen_metrics["seen_syntax_err_pct"],
        "seen_avg_latency_ms": seen_metrics["seen_avg_latency_ms"],
        "unseen_tool_acc_pct": unseen_metrics["unseen_tool_acc_pct"],
        "unseen_arga_em_pct": unseen_metrics["unseen_arga_em_pct"],
        "unseen_non_fc_rec_pct": unseen_metrics["unseen_non_fc_rec_pct"],
        "unseen_syntax_err_pct": unseen_metrics["unseen_syntax_err_pct"],
        "unseen_avg_latency_ms": unseen_metrics["unseen_avg_latency_ms"],
        "overall_tool_acc_pct": all_metrics["overall_tool_acc_pct"],
        "overall_arga_em_pct": all_metrics["overall_arga_em_pct"],
        "overall_non_fc_rec_pct": all_metrics["overall_non_fc_rec_pct"],
        "overall_avg_latency_ms": all_metrics["overall_avg_latency_ms"]
    }
    return output

# %%
tool_calling_vi_full.run(kbench.llm)
